import sqlite3
from contextlib import closing
from langchain_core.tools import tool

DB_PATH = "clinic.db"
ALLOWED_ROLES = {"viewer", "scheduler", "manager"}


@tool
def grant_staff_scheduling_access(staff_id: int, location_id: int, role: str) -> str:
    if role not in ALLOWED_ROLES:
        return "Invalid role: " + role
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            cur = conn.execute(
                "SELECT 1 FROM staff WHERE id = ? AND active = 1", (staff_id,)
            )
            if cur.fetchone() is None:
                return "Staff member not found or inactive"
            conn.execute(
                "INSERT INTO staff_location_roles (staff_id, location_id, role) "
                "VALUES (?, ?, ?) "
                "ON CONFLICT(staff_id, location_id) DO UPDATE SET role = excluded.role",
                (staff_id, location_id, role),
            )
    return "Staff %d now has role %s at location %d" % (staff_id, role, location_id)

import sqlite3


def update_appointment_notes(appointment_id: int, notes: str) -> str:
    if appointment_id <= 0:
        return "error: invalid appointment id"
    if not notes or not notes.strip():
        return "error: notes cannot be empty"
    if len(notes) > 2000:
        return "error: notes exceed 2000 characters"
    conn = sqlite3.connect("clinic.db")
    cur = conn.execute(
        "UPDATE appointments SET notes = ? WHERE id = ?", (notes.strip(), appointment_id)
    )
    conn.commit()
    conn.close()
    if cur.rowcount == 0:
        return "error: appointment not found"
    return "ok"

import sqlite3
from datetime import datetime, timedelta
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("clinic-scheduler")
DB = "clinic.db"


@mcp.tool()
def move_appointment_to_new_slot(appt_id: int, new_start: str, new_prov_id: int = None) -> dict:
    try:
        ns = datetime.fromisoformat(new_start)
    except ValueError:
        return {"ok": False, "error": "bad datetime"}
    if ns < datetime.now():
        return {"ok": False, "error": "slot is in the past"}

    db = sqlite3.connect(DB)
    try:
        c = db.cursor()
        c.execute(
            "SELECT provider_id, start_time, end_time, status FROM appointments WHERE id = ?",
            (appt_id,),
        )
        r = c.fetchone()
        if r is None:
            return {"ok": False, "error": "appointment not found"}
        pid, os_, oe, st = r
        if st in ("completed", "cancelled"):
            return {"ok": False, "error": "cannot move a " + st + " appointment"}

        dur = datetime.fromisoformat(oe) - datetime.fromisoformat(os_)
        ne = ns + dur
        tp = new_prov_id if new_prov_id is not None else pid

        c.execute("SELECT 1 FROM providers WHERE id = ?", (tp,))
        if c.fetchone() is None:
            return {"ok": False, "error": "provider not found"}

        c.execute(
            "SELECT id FROM appointments WHERE provider_id = ? AND id != ? "
            "AND status NOT IN ('cancelled') AND start_time < ? AND end_time > ?",
            (tp, appt_id, ne.isoformat(), ns.isoformat()),
        )
        cf = c.fetchone()
        if cf:
            return {"ok": False, "error": "slot conflicts with appointment %d" % cf[0]}

        c.execute(
            "UPDATE appointments SET provider_id = ?, start_time = ?, end_time = ? WHERE id = ?",
            (tp, ns.isoformat(), ne.isoformat(), appt_id),
        )
        db.commit()
        return {
            "ok": True,
            "appt_id": appt_id,
            "from": {"provider_id": pid, "start": os_},
            "to": {"provider_id": tp, "start": ns.isoformat(), "end": ne.isoformat()},
        }
    finally:
        db.close()
